use vstd::prelude::*;

verus! {

    // Given two distinct integers a and b in {1,2,3},
    // returns the unique integer in {1,2,3} different from both a and b.
    fn solve(a: i8, b: i8) -> (result: i8)
        requires
            1 <= a && a <= 3,
            1 <= b && b <= 3,
            a != b,
        ensures
            1 <= result && result <= 3,
            result != a,
            result != b,
    {
        let result = match (a, b) {
            (1, 2) | (2, 1) => 3,
            (1, 3) | (3, 1) => 2,
            (2, 3) | (3, 2) => 1,
            // All other cases are impossible under the preconditions
            _ => unreachable!(),
        };
        result
    }

}

fn main() {
    // some quick sanity checks (not verified by Verus)
    assert!(solve(1,2) == 3);
    assert!(solve(2,1) == 3);
    assert!(solve(1,3) == 2);
    assert!(solve(3,1) == 2);
    assert!(solve(2,3) == 1);
    assert!(solve(3,2) == 1);
}